const fs = require('fs');
const path = require('path');
const assert = require('assert');

const root = process.cwd();

function read(relativePath) {
  return fs.readFileSync(path.join(root, relativePath), 'utf8');
}

function assertIncludes(content, expected, label) {
  assert(content.includes(expected), `${label}: expected to include ${expected}`);
}

function assertNotIncludes(content, expected, label) {
  assert(!content.includes(expected), `${label}: expected not to include ${expected}`);
}

function assertMatches(content, pattern, label) {
  assert(pattern.test(content), `${label}: expected pattern ${pattern}`);
}

function assertOrder(content, expectedItems, label) {
  let previousIndex = -1;
  for (const item of expectedItems) {
    const index = content.indexOf(item, previousIndex + 1);
    assert(index >= 0, `${label}: expected to include ${item}`);
    assert(index > previousIndex, `${label}: expected ${item} to appear after previous item`);
    previousIndex = index;
  }
}

